head.script:
(function(){
  var ns="http://www.w3.org/1999/xhtml";
  if(document.contentType==="text/html")return;
  var create=document.createElement.bind(document),createNS=document.createElementNS.bind(document);
  var nativeGetById=document.getElementById.bind(document);
  document.createElement=function(name,options){return typeof name==="string"?createNS(ns,name,options):create(name)};
  function find(name){return document.getElementsByTagNameNS(ns,name)[0]||null}
  Object.defineProperty(document,"head",{configurable:true,get:function(){return find("head")}});
  Object.defineProperty(document,"body",{configurable:true,get:function(){return find("body")}});
  Object.defineProperty(document,"getElementById",{configurable:true,writable:true,value:function(id){
    var escaped=String(id).replace(/["\\]/g,"\\$&");
    return document.querySelector('[id="'+escaped+'"]')||nativeGetById(id)}});
})();
